"""Restore the complete geometry experiment source; leave data and results untouched."""
import argparse
import base64
from datetime import datetime
import gzip
import hashlib
import json
from pathlib import Path
import shutil

PAYLOAD = ''
DIGEST = 'c8b38a3c6131237ae0339cf1460143e9cb3a5fa5dc89efe4017853ea47753b5a'

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--project', required=True)
    args = parser.parse_args()
    project = Path(args.project).expanduser().resolve()
    raw = gzip.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != DIGEST:
        raise RuntimeError('Repair payload is damaged; download it again.')
    sources = json.loads(raw)
    backup = project / ('source_backup_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    for name, source in sources.items():
        relative = Path(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise RuntimeError('Invalid source path')
        if relative.suffix == '.py':
            compile(source, name, 'exec')
    for name, source in sources.items():
        target = project / name
        if target.exists() and target.read_bytes() != source.encode():
            saved = backup / name
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, saved)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(source.encode())
    for name, source in sources.items():
        if (project/name).read_bytes() != source.encode():
            raise RuntimeError('Verification failed: ' + name)
    print(f'Restored and verified {len(sources)} source files in {project}')
    if backup.exists():
        print('Previous changed source files backed up to:', backup)
    print('Data, outputs, and notebooks were not modified.')

if __name__ == '__main__':
    main()
